<?php
require_once __DIR__.'/../includes/auth.php';$a=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,['published','hidden','removed'],true)){db()->prepare('UPDATE reviews SET status=? WHERE id=?')->execute([$status,$id]);log_activity((int)$a['id'],'review_'.$status,'review',$id);}redirect('admin/reviews.php');}
$pg=pagination_window(30,60);$q=db()->prepare('SELECT r.id,r.request_id,r.rating,r.comment,r.status,r.created_at,c.name customer,t.name target FROM reviews r JOIN users c ON c.id=r.customer_id JOIN users t ON t.id=r.target_user_id ORDER BY r.id DESC LIMIT '.($pg['per']+1).' OFFSET '.$pg['offset']);$q->execute();$rows=$q->fetchAll();$hasNext=trim_page_results($rows,$pg['per']);release_session_lock();$pageTitle='Reviews — Admin';require __DIR__.'/../includes/header.php';?>
<div class="container py-4"><?php include __DIR__.'/_nav.php';?><h1>Review moderation</h1><div class="table-responsive"><table class="table"><tr><th>Review</th><th>Rating</th><th>Status</th><th>Moderate</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['customer'])?></b> → <?=e($r['target'])?><div><?=e($r['comment'])?></div></td><td><?=$r['rating']?>/5</td><td><?=e($r['status'])?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button name="status" value="published" class="btn btn-sm btn-outline-success">Publish</button><button name="status" value="hidden" class="btn btn-sm btn-outline-warning">Hide</button><button name="status" value="removed" class="btn btn-sm btn-outline-danger">Remove</button></form></td></tr><?php endforeach;?></table></div><?=pagination_nav($pg['page'],$hasNext)?></div><?php require __DIR__.'/../includes/footer.php';?>
